package net.officefloor.hq.app.dashboard;

import java.math.BigDecimal;
import java.util.List;

/**
 * Summary figures for the dashboard, with the clients who owe the most. What is outstanding is
 * given per currency, since amounts in different currencies cannot be added together. What is overdue
 * (left to pay on overdue invoices plus the late fees and instalment interest they have built up) is one total in
 * the home currency, and is also split by how many days overdue each invoice is.
 * What is outstanding is also given as one grand total in the home currency, each invoice converted at the
 * exchange rate from its own issue date. Also how many tasks are not yet done and how many of those are past their due date,
 * and the average number of days clients take to pay (from issue date to final payment on paid invoices; null when
 * there are none), and how many new clients were taken on in the current month, and what was billed (invoices issued and sent) in the current month, in the home
 * currency, and the share of everything billed that has been collected as a whole percentage (null when nothing
 * has been billed), and what was billed and what was collected (payments received) from the start of the year to
 * today, in the home currency.
 */
public record DashboardResponse(long clients, long projects, List<CurrencyTotal> outstanding,
        BigDecimal outstandingHome, long overdue,
        String homeCurrency, BigDecimal overdueAmount, OverdueBuckets overdueBuckets, List<TopClient> topClients,
        long openTasks, long overdueTasks, Long averageDaysToPay, long newClientsThisMonth,
        BigDecimal billingsThisMonth, Long collectionRate, BigDecimal billingsYearToDate,
        BigDecimal collectedYearToDate) {

    /** What is still owed in one currency. */
    public record CurrencyTotal(String currency, BigDecimal amount) {
    }

    /** What is overdue, in the home currency, by how many days past due: up to 30, 31 to 60, and more than 60. */
    public record OverdueBuckets(BigDecimal days0To30, BigDecimal days31To60, BigDecimal days60Plus) {
    }

    /** A client and what they still owe, in their currency and converted into the home currency. */
    public record TopClient(Long id, String name, String currency, BigDecimal outstanding, BigDecimal outstandingHome) {
    }
}
package net.officefloor.hq.app.dashboard;

import java.time.LocalDate;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/dashboard")
public class DashboardController {

    private final DashboardService service;

    public DashboardController(DashboardService service) {
        this.service = service;
    }

    @GetMapping
    public DashboardResponse summary() {
        return service.summary();
    }

    /** The tax charged on invoices issued on or between the given dates. */
    @GetMapping("/tax-summary")
    public TaxSummaryResponse taxSummary(@RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate from,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate to) {
        return service.taxSummary(from, to);
    }

    /** The sales tax charged on invoices issued on or between the given dates, broken down by tax rate. */
    @GetMapping("/tax-report")
    public TaxReportResponse taxReport(@RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate from,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate to) {
        return service.taxReport(from, to);
    }

    /**
     * The revenue billed on invoices issued on or between the given dates, broken down by job. Without both dates the
     * revenue is over all time.
     */
    @GetMapping("/revenue-report")
    public RevenueReportResponse revenueReport(
            @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate from,
            @RequestParam(required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate to) {
        return service.revenueReport(from, to);
    }

    /** The revenue billed in two periods (each on or between its dates), side by side. */
    @GetMapping("/revenue-compare")
    public RevenueComparisonResponse revenueComparison(
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate aFrom,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate aTo,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate bFrom,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate bTo) {
        return service.revenueComparison(aFrom, aTo, bFrom, bTo);
    }

    /** How old the debt across all clients is, in the home currency, split into age buckets. */
    @GetMapping("/aging-report")
    public AgingReportResponse agingReport() {
        return service.agingReport();
    }

    /** What was overdue at the close of each recent month, in the home currency, ending with the current month. */
    @GetMapping("/overdue-trend")
    public OverdueTrendResponse overdueTrend() {
        return service.overdueTrend();
    }

    /** The money expected in from the instalments still to be paid on sent invoices. */
    @GetMapping("/forecast")
    public ForecastResponse forecast() {
        return service.forecast();
    }
}
